cards.solution:
import java.text.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        String kata = in.nextLine().trim();
        List<String> produk = new ArrayList<>();
        while (in.hasNextLine()) {
            produk.add(in.nextLine().trim());
        }
        Collator collator = Collator.getInstance(Locale.forLanguageTag("id-ID"));
        collator.setStrength(Collator.PRIMARY);
        for (String p : produk) {
            if (collator.compare(p, kata) == 0) {
                System.out.println("Cocok: " + p);
            }
        }
    }
}
